import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Task939F_Variant4 {

    public static class FastScanner {
        private BufferedReader br;
        private String[] tokens;
        private int index;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            tokens = new String[0];
            index = 0;
        }

        public int nextInt() throws IOException {
            while (index >= tokens.length) {
                String line = br.readLine();
                if (line == null) throw new IOException("EOF");
                tokens = line.trim().split("\\s+");
                index = 0;
            }
            return Integer.parseInt(tokens[index++]);
        }
    }

    public static void SaveRotates(final int num) {
        if (minNumRotates == 0) minNumRotates = num;
        else minNumRotates = Math.min(minNumRotates, num);
    }

    public static void CalcRotates(int side, final int[] tmin, final int[] tmax,
                                   int noffset, int koffset, boolean isInterval) {
        if (tmin[0] > n || tmin[1] > n) return;
        if ((tmin[0] <= n && tmax[0] >= n) || (tmin[1] <= n && tmax[1] >= n)) {
            if ((tmax[0] < n && side == 1) || (tmax[1] < n && side == 0)) {
                SaveRotates(numRotates + 1);
            } else {
                SaveRotates(numRotates);
            }
            return;
        }
        if (koffset == k) return;

        if (isInterval) {
            if (kbeg[koffset] == kend[koffset]) {
                CalcRotates(side, tmin, tmax, noffset, koffset + 1, false);
                numRotates++;
                CalcRotates(1 - side, tmin, tmax, noffset, koffset + 1, false);
                numRotates--;
            } else {
                tmin[side] += kend[koffset] - kbeg[koffset];
                tmax[side] += kend[koffset] - kbeg[koffset];
                CalcRotates(side, tmin, tmax, kend[koffset], koffset + 1, false);
                tmin[side] -= kend[koffset] - kbeg[koffset];
                tmax[side] -= kend[koffset] - kbeg[koffset];

                tmax[side] += kend[koffset] - kbeg[koffset];
                tmax[1 - side] += kend[koffset] - kbeg[koffset];
                numRotates++;
                CalcRotates(1 - side, tmin, tmax, kend[koffset], koffset + 1, false);
                numRotates--;
                tmax[side] -= kend[koffset] - kbeg[koffset];
                tmax[1 - side] -= kend[koffset] - kbeg[koffset];

                tmax[side] += kend[koffset] - kbeg[koffset];
                tmin[1 - side] += 1;
                tmax[1 - side] += kend[koffset] - kbeg[koffset] - 1;
                numRotates += 2;
                CalcRotates(side, tmin, tmax, kend[koffset], koffset + 1, false);
                numRotates -= 2;
                tmax[side] -= kend[koffset] - kbeg[koffset];
                tmin[1 - side] -= 1;
                tmax[1 - side] -= kend[koffset] - kbeg[koffset] - 1;
            }
        } else {
            tmin[side] += kbeg[koffset] - noffset;
            tmax[side] += kbeg[koffset] - noffset;
            CalcRotates(side, tmin, tmax, kbeg[koffset], koffset, true);
            tmin[side] -= kbeg[koffset] - noffset;
            tmax[side] -= kbeg[koffset] - noffset;
        }
    }

    public static int[] kbeg;
    public static int[] kend;
    public static int n = 0;
    public static int k = 0;
    public static int numRotates = 0;
    public static int minNumRotates = 0;

    public static void main(final String[] args) throws IOException {
        final FastScanner scanner = new FastScanner();
        n = scanner.nextInt();
        k = scanner.nextInt();

        kbeg = new int[k];
        kend = new int[k];

        for (int i = 0; i < k; i++) {
            kbeg[i] = scanner.nextInt();
            kend[i] = scanner.nextInt();
        }
        final int[] tmin = new int[2];
        final int[] tmax = new int[2];

        CalcRotates(0, tmin, tmax, 0, 0, false);
        if (minNumRotates > 0) {
            System.out.println("Full");
            System.out.println(minNumRotates);
        } else {
            System.out.println("Hungry");
        }
    }
}
